Each accepted increment adds one; two successful calls must add two. models.mjs supplies a broken split read/write and a corrected complete update. Their checkpoint hook permits the test to control completion without sleeps; its position differs because the corrected update is indivisible. Edit only scenario.mjs to run a deterministic history through the public increment/value API. The verifier must reject broken behavior and accept the correction. Do not inspect function source/name to choose an expected outcome, hardcode which factory was supplied, or weaken the oracle. Preserve the same scenario for both. Record the concrete interleaving as the retained regression. No random library is needed for this minimal case.
import assert from 'node:assert/strict';
export async function runScenario(makeCounter) {
 const counter = makeCounter(async () => {});
 await counter.increment();
 await counter.increment();
 assert.equal(counter.value(), 2, 'two accepted increments must add two');
}
export function brokenFactory(checkpoint) {
 let value = 0;
 return {
  async increment() { const before = value; await checkpoint(); value = before + 1; },
  value() { return value; },
 };
}
export function fixedFactory(checkpoint) {
 let value = 0;
 return {
  async increment() { value += 1; await checkpoint(); },
  value() { return value; },
 };
}
import assert from 'node:assert/strict';
import { brokenFactory, fixedFactory } from './models.mjs';
import { runScenario } from './scenario.mjs';
await assert.rejects(() => runScenario(brokenFactory), assert.AssertionError,
 'the proposed scenario does not detect the lost update');
await runScenario(fixedFactory);
console.log('PASS scenario rejects broken behavior and accepts the complete update');

