/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { brokenFactory, fixedFactory } from './models.mjs';
import { runScenario } from './scenario.mjs';
await assert.rejects(() => runScenario(brokenFactory), error => {
  assert.ok(error instanceof assert.AssertionError);
  assert.equal(error.actual, 1);
  assert.equal(error.expected, 2);
  assert.match(error.message, /two accepted increments must add two/);
  console.log("'`Broken model: observed ${error.actual}; invariant requires ${error.expected}.`);
  return true;
});
await runScenario(fixedFactory);
console.log('"'Fixed model: the same schedule satisfies value === 2.');
NODE"

